command:
cd /testbed && echo '--- abstract/inheritance handling in ModelBase ---' && nl -ba django/db/models/base.py | sed -n '190,315p' && echo '--- lightweight reproduction and inheritance checks ---' && cat > /tmp/repro_get_display_light.py <<'EOF'
from django.conf import settings
settings.configure(INSTALLED_APPS=[], DATABASES={}, USE_I18N=False)
from django.apps import apps
apps.populate(settings.INSTALLED_APPS)
from django.db import models


class FooBar(models.Model):
    foo_bar = models.CharField(max_length=10, choices=[(1, 'foo'), (2, 'bar')])

    def __str__(self):
        return self.get_foo_bar_display()

    def get_foo_bar_display(self):
        return 'something'

    class Meta:
        app_label = 'repro'


class DisplayMixin:
    def get_foo_display(self):
        return 'mixin'


class WithMixin(DisplayMixin, models.Model):
    foo = models.CharField(max_length=10, choices=[(1, 'foo'), (2, 'bar')])

    class Meta:
        app_label = 'repro'


class AbstractCustom(models.Model):
    foo = models.CharField(max_length=10, choices=[(1, 'foo'), (2, 'bar')])

    def get_foo_display(self):
        return 'abstract custom'

    class Meta:
        abstract = True
        app_label = 'repro'


class ConcreteFromAbstractCustom(AbstractCustom):
    class Meta:
        app_label = 'repro'


class AbstractGenerated(models.Model):
    foo = models.CharField(max_length=10, choices=[(1, 'foo'), (2, 'bar')])

    class Meta:
        abstract = True
        app_label = 'repro'


class ConcreteFromAbstractGenerated(AbstractGenerated):
    class Meta:
        app_label = 'repro'


for label, cls, val in [
    ('FooBar', FooBar, 1),
    ('WithMixin', WithMixin, 1),
    ('ConcreteFromAbstractCustom', ConcreteFromAbstractCustom, 1),
    ('ConcreteFromAbstractGenerated', ConcreteFromAbstractGenerated, 1),
]:
    obj = cls(foo_bar=val) if cls is FooBar else cls(foo=val)
    print(label, '=>', obj.get_foo_bar_display() if cls is FooBar else obj.get_foo_display())
EOF
PYTHONPATH=/testbed python /tmp/repro_get_display_light.py
